#include <tfhe++.hpp>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <memory>
using namespace TFHEpp;
using L=lvl1param;
struct MiniDomain:lvl2param{static constexpr std::uint32_t n=4,k=1;};
struct ProbePKS:lvl21param{using domainP=MiniDomain;static constexpr std::uint32_t t=2,basebit=2;static constexpr double α=0x1p-24;};
struct Stats{std::size_t count=0;long double squares=0,sum=0;std::uint64_t maximum=0;void add(std::uint32_t residue){auto v=std::int64_t(std::bit_cast<std::int32_t>(residue));++count;sum+=v;squares+=static_cast<long double>(v)*v;maximum=std::max(maximum,std::uint64_t(std::abs(v)));}double rms()const{return std::sqrt(double(squares/count));}void json()const{std::cout<<"{\"count\":"<<count<<",\"rms\":"<<rms()<<",\"mean\":"<<double(sum/count)<<",\"maximum\":"<<maximum<<"}";}};
Polynomial<L> exact(const Polynomial<L>&a,const Key<L>&key){Polynomial<L> out{};for(std::size_t i=0;i<L::n;++i)for(std::size_t j=0;j<L::n;++j){const auto term=a[i]*key[j];if(i+j<L::n)out[i+j]+=term;else out[i+j-L::n]-=term;}return out;}
int main(){
 static_assert(L::n==1024&&L::k==1);Key<L> key;keyGen<L>(key);
 std::cout<<std::setprecision(17)<<"{\"source\":\"synthetic keys only; independent schoolbook integer phase audit\",\"trlwe\":[";
 for(int c=0;c<2;++c){const double sigma=c?256:128;Stats actual,sampler,rounding;for(int row=0;row<64;++row){TRLWE<L> ct;trlweSymEncryptZero<L>(ct,std::ldexp(sigma,-32),key);const auto product=exact(ct[0],key);Polynomial<L> approx;PolyMul<L>(approx,ct[0],key);for(std::size_t i=0;i<L::n;++i){actual.add(ct[1][i]-product[i]);sampler.add(ct[1][i]-approx[i]);rounding.add(approx[i]-product[i]);}}if(c)std::cout<<',';std::cout<<"{\"sigma\":"<<sigma<<",\"actual\":";actual.json();std::cout<<",\"sampler\":";sampler.json();std::cout<<",\"fft_rounding\":";rounding.json();std::cout<<'}';}
 Key<MiniDomain> source{};for(auto &v:source)v=1;Polynomial<L> function{};function[0]=1;auto pks=std::make_unique<PrivateKeySwitchingKey<ProbePKS>>();privkskgen<ProbePKS>(*pks,function,source,key);Stats pks_stats;std::size_t zero_checks=0;for(std::size_t i=0;i<=MiniDomain::n;++i)for(std::size_t j=0;j<ProbePKS::t;++j)for(std::size_t u=0;u<2;++u){const auto &row=(*pks)[i][j][u];const auto product=exact(row[0],key);for(std::size_t k=1;k<L::n;++k)pks_stats.add(row[1][k]-product[k]);TLWE<L> sample;SampleExtractIndex<L>(sample,row,1);if(tlweSymPhase<L>(sample,key)!=row[1][1]-product[1])return 1;++zero_checks;}
 std::cout<<"],\"pks\":{\"pks_parameter_sigma\":256,\"target_parameter_sigma\":128,\"observed_nonconstant_phase\":";pks_stats.json();std::cout<<",\"known_zero_extraction_checks\":"<<zero_checks<<"}}\n";
 return pks_stats.rms()>120&&pks_stats.rms()<136?0:2;
}
